def rearange_string(s):
  count_dict = {}
  for char in s:
    if char in count_dict:
      count_dict[char] += 1
    else:
      count_dict[char] = 1
  odd_count = sum(1 for count in count_dict.values() if count % 2 != 0)
  if odd_count > 1:
    return ""
  sorted_chars = sorted(count_dict.keys(), key=lambda x: count_dict[x])
  result = []
  for char in sorted_chars:
    while count_dict[char] > 0:
      result.append(char)
      count_dict[char] -= 1
  return ''.join(result)

